INSERT INTO stage3_candidate_seed VALUES
  ('COPA', 'Eomix 20', 'E01', 'stage3_copa_acbf8425541a4f44f522', 'Gaz beslemesi sorunu', 'gas_supply', 'İyonizasyon Arızası', 'Reset düğmesine basarak tekrar çalıştırın. Sorun devam ediyorsa gaz akışında sorun olabilir; öncelikle gazın açık olduğunu kontrol edin.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', '', 'Sorun devam ediyorsa gaz akışında sorun olabilir; öncelikle gazın açık olduğunu kontrol edin.', '', 'gaz akışında sorun'),
  ('COPA', 'Eomix 20', 'E03', 'stage3_copa_c14455871e2eee24dcb1', 'Tesisat sıcaklık sensörü sorunu', 'sensor', 'Tesisat Sensör Arızası', 'Tesisat suyu sıcaklığını duyan sensörlerden biri arızalıdır. Sensör değişikliği gerekir; arıza giderilene kadar ürün çalışmaz. COPA yetkili servisine başvurun.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', 'Tesisat Sensör Arızası', 'Tesisat suyu sıcaklığını duyan sensörlerden biri arızalıdır.', 'Tesisat Sensör', 'sensörlerden'),
  ('COPA', 'Eomix 20', 'E04', 'stage3_copa_e307241f56e8b455b588', 'Kullanım suyu sıcaklık sensörü sorunu', 'sensor', 'Kullanım Suyu Sensörü Arızası', 'Kullanım suyu sıcaklığını hisseden sensör arızalıdır. Arıza ekranda görünür; özel yazılım sayesinde cihaz iki devrede de çalışabilir. COPA yetkili servisine başvurun.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', 'Kullanım Suyu Sensörü Arızası', 'Kullanım suyu sıcaklığını hisseden sensör arızalıdır.', 'Kullanım Suyu Sensörü', 'sensör'),
  ('COPA', 'Eomix 20', 'E06', 'stage3_copa_d3709c862c5bec515de5', 'Yüksek limit / termik koruma noktası', 'electrical', 'Tesisat Devresinde Aşırı Sıcaklık', 'Tesisat sıcaklığı 95 °C''yi geçtiğinde ürün arızaya geçer; sıcaklık düşünce yeniden çalışır. Bu durum fan veya eşanjör sisteminde arızaya işaret edebilir. COPA yetkili servisine başvurun.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', 'Tesisat Devresinde Aşırı Sıcaklık', '', 'Aşırı Sıcaklık', ''),
  ('COPA', 'Eomix 20', 'E06', 'stage3_copa_f6d554cdc3d884a490e9', 'Fan sorunu', 'mechanical', 'Tesisat Devresinde Aşırı Sıcaklık', 'Tesisat sıcaklığı 95 °C''yi geçtiğinde ürün arızaya geçer; sıcaklık düşünce yeniden çalışır. Bu durum fan veya eşanjör sisteminde arızaya işaret edebilir. COPA yetkili servisine başvurun.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', '', 'Bu durum fan veya eşanjör sisteminde arızaya işaret edebilir.', '', 'fan'),
  ('COPA', 'Eomix 20', 'E06', 'stage3_copa_41ddb1267d0748652e39', 'Eşanjör/ısı bloğu sorunu', 'hydraulic', 'Tesisat Devresinde Aşırı Sıcaklık', 'Tesisat sıcaklığı 95 °C''yi geçtiğinde ürün arızaya geçer; sıcaklık düşünce yeniden çalışır. Bu durum fan veya eşanjör sisteminde arızaya işaret edebilir. COPA yetkili servisine başvurun.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', '', 'Bu durum fan veya eşanjör sisteminde arızaya işaret edebilir.', '', 'eşanjör'),
  ('COPA', 'Eomix 20', 'E08', 'stage3_copa_5ba2aeb022ac2d8ec392', 'Tesisat su basıncı/eksik su sorunu', 'hydraulic', 'Su Basınç Problemi', 'Tesisat su basıncı 0,4 barın altındaysa ürün arızaya geçer. Basıncı 1,5–2,0 bara çıkarın. Sorun sürerse basınç sensörü arızalı olabilir; hata sık tekrarlıyorsa tesisat devresinde su kaçağı olabilir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', 'Su Basınç Problemi', 'Tesisat su basıncı 0,4 barın altındaysa ürün arızaya geçer.', 'Su Basınç', 'su basıncı'),
  ('COPA', 'Eomix 20', 'E08', 'stage3_copa_2f7e535a8df83b7af9a1', 'Su basınç sensörü sorunu', 'sensor', 'Su Basınç Problemi', 'Tesisat su basıncı 0,4 barın altındaysa ürün arızaya geçer. Basıncı 1,5–2,0 bara çıkarın. Sorun sürerse basınç sensörü arızalı olabilir; hata sık tekrarlıyorsa tesisat devresinde su kaçağı olabilir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', '', 'Sorun sürerse basınç sensörü arızalı olabilir', '', 'basınç sensörü'),
  ('COPA', 'Eomix 20', 'E08', 'stage3_copa_c7ed335e0935146f7602', 'Su kaçağı/sızıntısı sorunu', 'hydraulic', 'Su Basınç Problemi', 'Tesisat su basıncı 0,4 barın altındaysa ürün arızaya geçer. Basıncı 1,5–2,0 bara çıkarın. Sorun sürerse basınç sensörü arızalı olabilir; hata sık tekrarlıyorsa tesisat devresinde su kaçağı olabilir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', '', 'hata sık tekrarlıyorsa tesisat devresinde su kaçağı olabilir.', '', 'su kaçağı'),
  ('COPA', 'Eomix 20', 'E09', 'stage3_copa_6ef3ef3d8fd83c0d9b59', 'Termostat/sıcaklık sınırlayıcısı sorunu', 'sensor', 'Aşırı Isınma Termostat Arızası', 'Su sıcaklığı 95 °C''nin üzerine çıktığında güvenlik termostatı açar ve ürün arızaya geçer; yaklaşık 80 °C''nin altında termostat yeniden kapanır. Arıza tekrarlıyorsa fan veya eşanjör kontrolü gerekir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', 'Aşırı Isınma Termostat Arızası', '', ' Termostat', ''),
  ('COPA', 'Eomix 20', 'E09', 'stage3_copa_0d9ad1d4360664e11ac2', 'Fan sorunu', 'mechanical', 'Aşırı Isınma Termostat Arızası', 'Su sıcaklığı 95 °C''nin üzerine çıktığında güvenlik termostatı açar ve ürün arızaya geçer; yaklaşık 80 °C''nin altında termostat yeniden kapanır. Arıza tekrarlıyorsa fan veya eşanjör kontrolü gerekir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', '', 'Arıza tekrarlıyorsa fan veya eşanjör kontrolü gerekir.', '', 'fan'),
  ('COPA', 'Eomix 20', 'E09', 'stage3_copa_0c7f310decd4cd315db8', 'Eşanjör/ısı bloğu sorunu', 'hydraulic', 'Aşırı Isınma Termostat Arızası', 'Su sıcaklığı 95 °C''nin üzerine çıktığında güvenlik termostatı açar ve ürün arızaya geçer; yaklaşık 80 °C''nin altında termostat yeniden kapanır. Arıza tekrarlıyorsa fan veya eşanjör kontrolü gerekir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', '', 'Arıza tekrarlıyorsa fan veya eşanjör kontrolü gerekir.', '', 'eşanjör'),
  ('COPA', 'Eomix 20', 'E10', 'stage3_copa_b0f44804459b053eab44', 'Yüksek tesisat su basıncı sorunu', 'hydraulic', 'Yüksek Su Basıncı Arızası', 'Tesisat su basıncı 3,5 barın üzerine çıktığında ürün arızaya geçer; 3,0 barın altına düşünce hata giderilir. Sık tekrarlıyorsa genleşme tankında sorun olabilir; servis kontrolü gerekir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', 'Yüksek Su Basıncı Arızası', 'Tesisat su basıncı 3,5 barın üzerine çıktığında ürün arızaya geçer; 3,0 barın altına düşünce hata giderilir.', 'Su Basıncı', 'su basıncı'),
  ('COPA', 'Eomix 20', 'E10', 'stage3_copa_33e7ca0d616087f4636d', 'Genleşme kabı sorunu', 'hydraulic', 'Yüksek Su Basıncı Arızası', 'Tesisat su basıncı 3,5 barın üzerine çıktığında ürün arızaya geçer; 3,0 barın altına düşünce hata giderilir. Sık tekrarlıyorsa genleşme tankında sorun olabilir; servis kontrolü gerekir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', '', 'Sık tekrarlıyorsa genleşme tankında sorun olabilir; servis kontrolü gerekir.', '', 'genleşme tankında'),
  ('COPA', 'Eomix 20', 'E17', 'stage3_copa_95b36552a68837e9f2c3', 'Baca gazı sensörü sorunu', 'sensor', 'Baca Sensörü Arızası', 'Baca sıcaklığı yükseldiğinde güvenlik sensörü cihazı arızaya geçirir; sıcaklık düşünceye kadar hata sürer. Sık tekrarlıyorsa fan ve eşanjör grubunun kontrolü gerekir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf', 'official_manufacturer', 'Baca Sensörü Arızası', 'Baca sıcaklığı yükseldiğinde güvenlik sensörü cihazı arızaya geçirir; sıcaklık düşünceye kadar hata sürer.', 'Baca Sensörü', 'sensörü'),
